<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api'
import PageHeader from '../components/PageHeader.vue'
import SectionCard from '../components/SectionCard.vue'
import StatusBadge from '../components/StatusBadge.vue'
import SegmentTabs from '../components/SegmentTabs.vue'
import ActionIcon from '../components/ActionIcon.vue'
const route=useRoute(),router=useRouter();const step=ref('model'),profile=ref<any>(),model=ref<any>(),platforms=ref<any[]>([]),selected=ref<Record<string,string>>({}),enabled=ref<Record<string,boolean>>({}),error=ref(''),creating=ref(false),created=ref<any>()
const steps=[{id:'model',label:'1 选择模型'},{id:'platform',label:'2 选择平台'},{id:'confirm',label:'3 核对提交'}]
const groups=computed(()=>Object.entries(platforms.value.reduce((out:Record<string,any[]>,x:any)=>{(out[x.platform_type_name||x.platform_id]||=[]).push(x);return out},{})).map(([name,items])=>[name,[...(items as any[])].sort((a,b)=>String(b.version||'').localeCompare(String(a.version||''),undefined,{numeric:true}))]))
const chosen=computed(()=>Object.entries(selected.value).filter(([name])=>enabled.value[name]).map(([,id])=>platforms.value.find(x=>x.id===id)).filter(Boolean) as any[])
const formatBytes=(value?:number)=>!value?'未记录':value<1024?`${value} 字节`:value<1024*1024?`${(value/1024).toFixed(1)} KB`:`${(value/1024/1024).toFixed(1)} MB`
const analysis=computed(()=>profile.value?.summary||profile.value?.analysis?.summary||{})
const opsetSummary=computed(()=>{const entries=analysis.value.opset_imports||[];return entries.length?entries.map((entry:any)=>`${entry.domain||'ai.onnx'} ${entry.version}`).join(' / '):'未记录'})
const operatorSummary=computed(()=>Object.entries(analysis.value.operator_counts||{}).sort((a:any,b:any)=>b[1]-a[1]).slice(0,6).map(([name,count])=>`${name} ${count}`).join(' · ')||'未记录算子明细')
const ioSummary=computed(()=>{const entries=[...(analysis.value.inputs||[]),...(analysis.value.outputs||[])];return entries.slice(0,2).map((item:any)=>`${item.name||'未命名'} ${Array.isArray(item.shape)?`[${item.shape.join(' × ')}]`:''}`.trim()).join('；')||'未记录输入/输出形状'})
async function load(){try{profile.value=await api(`/model-profiles/${route.query.profile_id}`);model.value=await api(`/model-assets/${profile.value.model_asset_id}`);platforms.value=await api('/evaluation-platforms');selected.value=Object.fromEntries(groups.value.map(([name,items]:any)=>[name,items.find((x:any)=>x.available)?.id||'']));enabled.value=Object.fromEntries(groups.value.map(([name,items]:any)=>[name,items.some((x:any)=>x.available)]));}catch(cause){error.value=cause instanceof Error?cause.message:'未能读取可创建评估的模型或平台。'}}
function next(){if(step.value==='model'){step.value='platform';return}if(step.value==='platform'){if(!chosen.value.length){error.value='请至少选择一个可调度平台。';return}error.value='';step.value='confirm'}}
function previous(){step.value=step.value==='confirm'?'platform':'model'}
async function submit(){if(!chosen.value.length)return;creating.value=true;error.value='';try{created.value=await api('/evaluation-flows',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model_profile_id:profile.value.id,catalog_ids:chosen.value.map(x=>x.id),preset:'standard-performance-1.0'})})}catch(cause){error.value=cause instanceof Error?cause.message:'创建评估失败。'}finally{creating.value=false}}
async function view(){if(created.value?.id)await router.push(`/flows/${created.value.id}`)}
onMounted(load)
</script>
<template><section class="page create-flow-page"><PageHeader title="创建评估" description="按三步完成选择：模型、目标平台、核对提交。提交后系统会自动执行后续评估。" eyebrow="模型评估"/><p v-if="error" class="feedback error">{{error}}</p><SegmentTabs v-model="step" :items="steps"/><SectionCard v-if="step==='model'" title="步骤 1：确认模型" description="请核对本次评估所使用的模型与结构分析摘要。"><div v-if="profile" class="model-selection-card"><header><div><small>已选择模型</small><h3>{{model?.original_filename||'正在读取模型名称…'}}</h3><code>{{model?.sha256?.slice(0,16)||profile.onnx_sha256?.slice(0,16)}}…</code></div><StatusBadge tone="success">结构分析已完成</StatusBadge></header><div class="model-facts"><div><small>文件大小</small><strong>{{formatBytes(model?.size_bytes)}}</strong></div><div><small>节点规模</small><strong>{{analysis.node_count??'未记录'}} 个节点</strong></div><div><small>算子种类</small><strong>{{analysis.operator_type_count??(Object.keys(analysis.operator_counts||{}).length||'未记录')}} 类</strong></div><div><small>ONNX Opset 版本</small><strong>{{opsetSummary}}</strong></div><div><small>分析器</small><strong>{{profile.analyzer_version}}</strong></div></div><div class="model-analysis"><p><b>主要算子：</b>{{operatorSummary}}</p><p><b>输入 / 输出：</b>{{ioSummary}}</p><p class="model-hint">本次会使用该模型的冻结分析结果创建受控评估；性能结论仅适用于本次选定平台与执行条件。</p></div></div><p v-else class="muted">正在读取模型与结构分析信息…</p><div class="wizard-actions"><button class="button-primary" :disabled="!profile||!model" @click="next"><ActionIcon name="create"/>下一步：选择平台</button></div></SectionCard><SectionCard v-if="step==='platform'" title="步骤 2：选择目标平台" description="您可选择一个或多个可用平台。同一平台类型如有多个版本，只能选择其中一个版本。"><div class="platform-choice-grid"><article v-for="[name,items] in groups" :key="String(name)" class="platform-choice-card" :class="{unavailable:!(items as any[]).some(x=>x.available)}"><header><label><input v-model="enabled[String(name)]" type="checkbox" :disabled="!(items as any[]).some(x=>x.available)"><strong>{{name}}</strong></label><StatusBadge :tone="(items as any[]).some(x=>x.available)?'success':'warning'">{{(items as any[]).some(x=>x.available)?'可调度':'不可用'}}</StatusBadge></header><label v-for="item in items as any[]" :key="item.id" class="version-option" :class="{disabled:!item.available}"><input v-model="selected[String(name)]" type="radio" :value="item.id" :disabled="!item.available||!enabled[String(name)]"><span>{{item.version||item.display_name}}</span><small>{{item.available?'系统将自动执行编译和板端性能测试':item.detail}}</small></label></article></div><p class="muted">本次使用 standard-performance-1.0 预设。精度、稳定性、功耗和部署推荐需要独立验证，不会在本次流程中自动推断。</p><div class="wizard-actions"><button class="button-secondary" @click="previous">上一步</button><button class="button-primary" @click="next"><ActionIcon name="create"/>下一步：核对提交</button></div></SectionCard><SectionCard v-if="step==='confirm'" title="步骤 3：核对并提交" description="确认后会创建一条评估流程；各平台独立执行，结果会自动汇总到同一份评估中。"><div class="review-list"><p><strong>模型：</strong>{{model?.original_filename||profile?.id}}（{{formatBytes(model?.size_bytes)}}，{{analysis.node_count??'未记录'}} 个节点，ONNX Opset {{opsetSummary}}）</p><p><strong>选择平台：</strong>{{chosen.map(x=>`${x.platform_type_name} ${x.version}`).join(' + ')}}</p><p><strong>固定预设：</strong>standard-performance-1.0</p><p><strong>执行内容：</strong><span v-for="item in chosen" :key="item.id">{{item.platform_id==='X5'?'X5 编译 → X5 板端性能':'S100 编译 → S100 板端性能'}}；</span></p><p><strong>结果说明：</strong>本次会记录实际执行结果；输出一致性、精度、稳定性、功耗与部署推荐仍需相应的独立验证。</p></div><div class="wizard-actions"><button class="button-secondary" @click="previous">上一步</button><button class="button-primary" :disabled="creating" @click="submit"><ActionIcon name="create"/>{{creating?'正在创建…':'提交评估'}}</button></div></SectionCard><div v-if="created" class="modal-backdrop"><section class="modal card"><h2>评估已创建</h2><p>流程号：<strong>{{created.id}}</strong></p><p>系统会依次执行已选平台的编译和板端性能阶段。您可在流程详情查看进度、结果、报告和 PDF。</p><button class="button-secondary" @click="created=undefined">我知道了</button><button class="button-primary" @click="view"><ActionIcon name="view"/>立即查看</button></section></div></section></template>
